const EXPANDED = atom({ plugin: 'workflow-map', key: 'expanded' } as const, false)
const PENDING = atom({ plugin: 'workflow-map', key: 'pending' } as const, false)
const DONE_TURNS = atom({ plugin: 'workflow-map', key: 'doneTurns' } as const, 0)
