  WORDING

const SCHEMA = {
  type: 'object',
  properties: {
    op: { type: 'string', enum: ['new_plan', 'set_plan', 'upsert', 'status', 'insert', 'remove', 'show'] },
    title: { type: 'string', description: 'new_plan: a short name for the task, in the user\'s language' },
